static void test_deep_copy_max_depth(void) {
    json_t *json;
    json_t *copy;
    int i;

    json = json_array();
    for (i = 1; i < JSON_PARSER_MAX_DEPTH + 100; i++) {
        json_t *outer = json_array();
        json_array_append_new(outer, json);
        json = outer;
    }

    copy = json_deep_copy(json);
    if (copy)
        fail("json_deep_copy didn't fail for a too deeply nested structure!");

    json_decref(json);
}

static void max_depth() {
    json_t *json;
    char *result;

    /* A structure nested exactly to the limit must still serialize. */
    json = build_nested_array(JSON_PARSER_MAX_DEPTH);
    result = json_dumps(json, 0);
    if (!result)
        fail("json_dumps failed for a structure within the depth limit");
    free(result);
    json_decref(json);

    /* A structure nested deeper than the limit must fail cleanly rather
       than overflow the stack. */
    json = build_nested_array(JSON_PARSER_MAX_DEPTH + 100);
    if (json_dumps(json, 0) != NULL)
        fail("json_dumps didn't fail for a too deeply nested structure");
    json_decref(json);
}

static void test_equal_max_depth() {
    json_t *value1, *value2;
    int i;

    value1 = json_array();
    value2 = json_array();
    for (i = 1; i < JSON_PARSER_MAX_DEPTH + 100; i++) {
        json_t *outer1 = json_array();
        json_t *outer2 = json_array();
        json_array_append_new(outer1, value1);
        json_array_append_new(outer2, value2);
        value1 = outer1;
        value2 = outer2;
    }

    /* The structures are structurally equal, but exceed the depth limit;
       json_equal must bail out rather than overflow the stack. */
    if (json_equal(value1, value2))
        fail("json_equal didn't bail out for a too deeply nested structure");

    json_decref(value1);
    json_decref(value2);
}

extern "C" int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size)
{
  json_error_t error;
  unsigned char dump_mode;

  // Enable or disable diagnostics based on the FUZZ_VERBOSE environment flag.
  enable_diags = (getenv("FUZZ_VERBOSE") != NULL);

  FUZZ_DEBUG("Input data length: %zd", size);

  if (size < NUM_COMMAND_BYTES)
  {
    return 0;
  }

  // Use the first sizeof(size_t) bytes as load flags.
  size_t load_flags = *(const size_t*)data;
  data += sizeof(size_t);

  FUZZ_DEBUG("load_flags: 0x%zx\n"
             "& JSON_REJECT_DUPLICATES =  0x%zx\n"
             "& JSON_DECODE_ANY =         0x%zx\n"
             "& JSON_DISABLE_EOF_CHECK =  0x%zx\n"
             "& JSON_DECODE_INT_AS_REAL = 0x%zx\n"
             "& JSON_ALLOW_NUL =          0x%zx\n",
             load_flags,
             load_flags & JSON_REJECT_DUPLICATES,
             load_flags & JSON_DECODE_ANY,
             load_flags & JSON_DISABLE_EOF_CHECK,
             load_flags & JSON_DECODE_INT_AS_REAL,
             load_flags & JSON_ALLOW_NUL);

  // Use the next sizeof(size_t) bytes as dump flags.
  size_t dump_flags = *(const size_t*)data;
  data += sizeof(size_t);

  FUZZ_DEBUG("dump_flags: 0x%zx\n"
             "& JSON_MAX_INDENT =     0x%zx\n"
             "& JSON_COMPACT =        0x%zx\n"
             "& JSON_ENSURE_ASCII =   0x%zx\n"
             "& JSON_SORT_KEYS =      0x%zx\n"
             "& JSON_PRESERVE_ORDER = 0x%zx\n"
             "& JSON_ENCODE_ANY =     0x%zx\n"
             "& JSON_ESCAPE_SLASH =   0x%zx\n"
             "& JSON_REAL_PRECISION = 0x%zx\n"
             "& JSON_EMBED =          0x%zx\n",
             dump_flags,
             dump_flags & JSON_MAX_INDENT,
             dump_flags & JSON_COMPACT,
             dump_flags & JSON_ENSURE_ASCII,
             dump_flags & JSON_SORT_KEYS,
             dump_flags & JSON_PRESERVE_ORDER,
             dump_flags & JSON_ENCODE_ANY,
             dump_flags & JSON_ESCAPE_SLASH,
             ((dump_flags >> 11) & 0x1F) << 11,
             dump_flags & JSON_EMBED);

  // Use the next byte as the dump mode.
  dump_mode = data[0];
  data++;

  FUZZ_DEBUG("dump_mode: 0x%x", (unsigned int)dump_mode);

  // Remove the command bytes from the size total.
  size -= NUM_COMMAND_BYTES;

  // Attempt to load the remainder of the data with the given load flags.
  const char* text = reinterpret_cast<const char *>(data);
  json_t* jobj = json_loadb(text, size, load_flags, &error);

  if (jobj == NULL)
  {
    return 0;
  }

  if (dump_mode & FUZZ_DUMP_STRING)
  {
    // Dump as a string. Remove indents so that we don't run out of memory.
    char *out = json_dumps(jobj, dump_flags & ~JSON_MAX_INDENT);
    if (out != NULL)
    {
      free(out);
    }
  }
  else
  {
    // Default is callback mode.
    //
    // Attempt to dump the loaded json object with the given dump flags.
    uint64_t counter = 0;

    json_dump_callback(jobj, json_dump_counter, &counter, dump_flags);
    FUZZ_DEBUG("Counter function counted %" PRIu64 " bytes.", counter);
  }

  if (jobj)
  {
    json_decref(jobj);
  }

  return 0;
}

extern "C" int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size)
{
    if (size < 2)
        return 0;

    /* Use first byte to select format variant, rest as JSON input */
    uint8_t variant = data[0] % 8;
    const char *json_str = (const char *)(data + 1);
    size_t json_len = size - 1;

    json_error_t error;
    json_t *root = json_loadb(json_str, json_len,
                               JSON_DECODE_ANY | JSON_ALLOW_NUL, &error);
    if (root == NULL)
        return 0;

    /* Exercise json_deep_copy on whatever we parsed */
    json_t *copy = json_deep_copy(root);
    if (copy != NULL)
        json_decref(copy);

    /* Exercise json_dumps with various flags */
    const int flag_sets[] = {
        0,
        JSON_COMPACT,
        JSON_ENSURE_ASCII,
        JSON_SORT_KEYS,
        JSON_COMPACT | JSON_ENSURE_ASCII,
    };
    int flags = flag_sets[variant % 5];
    char *dumped = json_dumps(root, flags);
    if (dumped != NULL) {
        /* Re-load the dumped output for round-trip check */
        json_t *reparsed = json_loads(dumped, 0, NULL);
        if (reparsed != NULL)
            json_decref(reparsed);
        free(dumped);
    }

    /* Exercise json_unpack with simple format strings if root is an object */
    if (json_is_object(root)) {
        json_t *val = NULL;
        const char *key = NULL;
        /* Unpack first key-value pair */
        void *iter = json_object_iter(root);
        if (iter != NULL) {
            key = json_object_iter_key(iter);
            val  = json_object_iter_value(iter);
            (void)key;
            (void)val;
        }

        /* json_unpack with "o" format — extract object */
        json_t *out_obj = NULL;
        json_unpack(root, "o", &out_obj);

        /* json_unpack with "{s?o}" — optional key lookup */
        json_t *field = NULL;
        json_unpack(root, "{s?o}", "data", &field);
    }

    /* Exercise json_unpack on array */
    if (json_is_array(root) && json_array_size(root) > 0) {
        json_t *first = NULL;
        json_unpack(root, "[o!]", &first);
    }

    json_decref(root);
    return 0;
}

